/**
 * Why an inbound media key was discarded — the answer to "why can't I hear
 * them?", which the crate computes and used to drop on the floor.
 */
export enum FfiKeyRejection {
    Cleartext,
    UnknownOrigin,
    SenderMismatch,
    DeviceMismatch,
    UnattributableMember,
    NotCrossSigned,
    WrongRoom,
    Outdated,
    NotManagingKeys
}

const FfiConverterTypeFfiKeyRejection = (() => {
    type TypeName = FfiKeyRejection;
    class FFIConverter extends AbstractFfiConverterByteArray<TypeName> {
        readFromCursor(c: Cursor): TypeName {
            switch (c.readI32()) {
                case 1: return FfiKeyRejection.Cleartext;
                case 2: return FfiKeyRejection.UnknownOrigin;
                case 3: return FfiKeyRejection.SenderMismatch;
                case 4: return FfiKeyRejection.DeviceMismatch;
                case 5: return FfiKeyRejection.UnattributableMember;
                case 6: return FfiKeyRejection.NotCrossSigned;
                case 7: return FfiKeyRejection.WrongRoom;
                case 8: return FfiKeyRejection.Outdated;
                case 9: return FfiKeyRejection.NotManagingKeys;
                default: throw new UniffiInternalError.UnexpectedEnumCase();
            }
        }
        writeIntoCursor(value: TypeName, c: Cursor): void {
            switch (value) {
                case FfiKeyRejection.Cleartext: return c.writeI32(1);
                case FfiKeyRejection.UnknownOrigin: return c.writeI32(2);
                case FfiKeyRejection.SenderMismatch: return c.writeI32(3);
                case FfiKeyRejection.DeviceMismatch: return c.writeI32(4);
                case FfiKeyRejection.UnattributableMember: return c.writeI32(5);
                case FfiKeyRejection.NotCrossSigned: return c.writeI32(6);
                case FfiKeyRejection.WrongRoom: return c.writeI32(7);
                case FfiKeyRejection.Outdated: return c.writeI32(8);
                case FfiKeyRejection.NotManagingKeys: return c.writeI32(9);
            }
        }
        allocationSize(value: TypeName): number {
            return 4;
        }
    }
    return new FFIConverter();
})();

